1	// 念念 · 陈列室 —— 核心数据模型（B1 地基）
2	//
3	// 关系：Scene 与 Item 多对多，经 Placement 关联。
4	// 一件 Item 可被摆进多个 Scene（每次摆放是一条 Placement），
5	// 同一 Scene 里也可摆多件 Item。
6	// 「故事」挂在 Item 本身（跨场景同步），而非挂在某次 Placement 上；
7	// 位置/大小/角度/层级（x/y/scale/rotation/z）才随「这次摆放」走。
8	
9	/** 场景 = 一个画布（房间空间），绑定一张预置背景图。背景不可重复，上限 3。 */
10	export interface Scene {
11	  id: string;
12	  name: string;
13	  /** 关联内置背景素材的 id（见 assets/manifest 的 BACKGROUNDS） */
14	  backgroundId: string;
15	}
16	
17	/** 物件 = 想陈列的旧物，带一段用户写的故事（故事挂物件本身，跨场景同步）。 */
18	export interface Item {
19	  id: string;
20	  name: string;
21	  /** 透明抠图的图片地址（构建后为打包资源 URL） */
22	  imageSrc: string;
23	  /** 用户写的故事；初始为空串 */
24	  story: string;
25	}
26	
27	/** 摆放 = 某个 Item 在某个 Scene 中的一次落位（多对多的连接实体）。 */
28	export interface Placement {
29	  id: string;
30	  sceneId: string;
31	  itemId: string;
32	  /** 画布内水平位移（px，相对画布左上角） */
33	  x: number;
34	  /** 画布内垂直位移（px，相对画布左上角） */
35	  y: number;
36	  /** 缩放倍率（1 = 原始尺寸） */
37	  scale: number;
38	  /** 旋转角度（deg） */
39	  rotation: number;
40	  /** 层级（同场景内的堆叠顺序，越大越靠上） */
41	  z: number;
42	}
43	
44	/** 编辑 / 游客 双模式。 */
45	export type Mode = 'edit' | 'guest';
