// 念念 · 陈列室 —— 核心数据模型（B1 地基）
//
// 关系：Scene 与 Item 多对多，经 Placement 关联。
// 一件 Item 可被摆进多个 Scene（每次摆放是一条 Placement），
// 同一 Scene 里也可摆多件 Item。
// 「故事」挂在 Item 本身（跨场景同步），而非挂在某次 Placement 上；
// 位置/大小/角度/层级（x/y/scale/rotation/z）才随「这次摆放」走。

/** 场景 = 一个画布（房间空间），绑定一张预置背景图。背景不可重复，上限 3。 */
export interface Scene {
  id: string;
  name: string;
  /** 关联内置背景素材的 id（见 assets/manifest 的 BACKGROUNDS） */
  backgroundId: string;
}

/** 物件 = 想陈列的旧物，带一段用户写的故事（故事挂物件本身，跨场景同步）。 */
export interface Item {
  id: string;
  name: string;
  /** 透明抠图的图片地址（构建后为打包资源 URL） */
  imageSrc: string;
  /** 用户写的故事；初始为空串 */
  story: string;
}

/** 摆放 = 某个 Item 在某个 Scene 中的一次落位（多对多的连接实体）。 */
export interface Placement {
  id: string;
  sceneId: string;
  itemId: string;
  /** 画布内水平位移（px，相对画布左上角） */
  x: number;
  /** 画布内垂直位移（px，相对画布左上角） */
  y: number;
  /** 缩放倍率（1 = 原始尺寸） */
  scale: number;
  /** 旋转角度（deg） */
  rotation: number;
  /** 层级（同场景内的堆叠顺序，越大越靠上） */
  z: number;
}

/** 编辑 / 游客 双模式。 */
export type Mode = 'edit' | 'guest';

/**
 * 全量应用状态 —— LocalStorage 全量读写的单一载体（非增量）。
 * schemaVersion 用于持久化格式版本管理与后续迁移。
 */
export interface GalleryState {
  schemaVersion: number;
  scenes: Scene[];
  items: Item[];
  placements: Placement[];
  /** 当前激活的场景 id；无场景时为 null */
  activeSceneId: string | null;
  mode: Mode;
}

content.content:
1	// 画布：当前场景的展示区域。背景铺满（cover）+ 暗角；摆放的物件绝对定位 + transform。
2	// 变换手柄（拖/缩/转）属 M2，本 sprint 只呈现当前场景与已放物件（布局状态还原）。
3	import type { GalleryState, Scene } from '../model/types';
4	import { getBackgroundById, getItemAssetById } from '../assets/manifest';
5	import { placementsOfScene } from '../state/gallery';
6	
7	interface CanvasProps {
8	  state: GalleryState;
9	  scene: Scene | undefined;
10	}
11	
12	export function Canvas({ state, scene }: CanvasProps) {
13	  if (!scene) {
14	    return (
15	      <section className="stage stage--empty" data-testid="canvas" aria-label="画布">
16	        <div className="stage__placeholder">
17	          <p className="stage__placeholder-title">还没有场景</p>
18	          <p className="stage__placeholder-sub">
19	            {state.mode === 'edit' ? '点上方「＋ 新场景」，绑定一张背景开始陈列' : '暂无可预览的场景'}
20	          </p>
21	        </div>
22	      </section>
23	    );
24	  }
25	
26	  const bg = getBackgroundById(scene.backgroundId);
27	  const placements = placementsOfScene(state, scene.id);
28	
29	  return (
30	    <section
31	      className="stage"
32	      data-testid="canvas"
33	      data-scene-id={scene.id}
34	      aria-label={`画布 · ${scene.name}`}
35	    >
36	      <div
37	        className="stage__bg"
38	        data-testid="canvas-bg"
39	        style={bg ? { backgroundImage: `url(${bg.imageSrc})` } : undefined}
40	      />
41	
42	      {placements.map((p) => {
43	        const asset = getItemAssetById(p.itemId);
44	        if (!asset) return null;
45	        return (
46	          <img
47	            key={p.id}
48	            className="stage__node"
49	            data-testid="placement"
50	            data-placement-id={p.id}
51	            data-item-id={p.itemId}
52	            src={asset.imageSrc}
53	            alt={asset.name}
54	            style={{
55	              left: `${p.x}px`,
56	              top: `${p.y}px`,
57	              transform: `rotate(${p.rotation}deg) scale(${p.scale})`,
58	              zIndex: p.z,
59	            }}
60	          />
61	        );
62	      })}
63	
64	      {placements.length === 0 && state.mode === 'edit' && (
65	        <p className="stage__hint" data-testid="canvas-hint">
66	          从左侧物件抽屉点选，放入这个房间
67	        </p>
68	      )}
69	    </section>
70	  );
71	}
72

