// 物件抽屉：纵列缩略卡，列出全部 14 件内置物件（来自 manifest 的 ITEMS）。
// 编辑模式 + 有激活场景时，点缩略卡把物件放入当前画布（建一条 placement）。
import { ITEMS } from '../assets/manifest';

interface ItemTrayProps {
  canPlace: boolean;
  onPlaceItem: (itemId: string) => void;
}

export function ItemTray({ canPlace, onPlaceItem }: ItemTrayProps) {
  return (
    <aside className="tray" data-testid="tray" aria-label="物件抽屉">
      <h4>物件</h4>
      <p className="hint">{canPlace ? '点一下放入房间' : '先建/选一个场景'}</p>

      {ITEMS.map((item) => (
        <button
          type="button"
          key={item.id}
          className="thumb"
          data-testid="tray-item"
          data-item-id={item.id}
          disabled={!canPlace}
          aria-disabled={!canPlace}
          title={canPlace ? `把「${item.name}」放入房间` : item.name}
          onClick={() => canPlace && onPlaceItem(item.id)}
        >
          <img className="itm" src={item.thumbSrc} alt={item.name} loading="lazy" />
          <span>{item.name}</span>
        </button>
      ))}
    </aside>
  );
}

