478	// stdout 给出 {generation, tickSeq}；这一轮后续所有写类调用都必须带着这个代数（--gen）。
479	// 可选参数：--session 会话标识（记账归属靠它，见下方取值优先级）；--employee 登记成哪个员工
480	//          （默认「主控」）；--lease-ms 租约时长毫秒（默认 15 分钟）；--pid 持有者进程号
481	//          （默认本进程，带外的壳可传自己的常驻进程号，让探活盯对地方）。
482	//
483	// 会话标识取值优先级（E 项：会话标识机器盖章，tick-begin 不再只认自报值）：
484	//   ① SessionStart 钩子经 session-mark 盖的机器戳（runtime/current-session.json）——
485	//      真实、不可伪造，是记账归属的首选依据；
486	//   ② 没盖章（比如非 Claude Code 环境手工跑、钩子还没来得及跑）时退回显式 --session
487	//      （兼容旧写法，模型自报）；
488	//   ③ 两样都没有，退回「进程-<pid>」的兜底标识（老行为，非记账场景够用）。
489	// 机器戳和 --session 两样都有但对不上时，以机器戳为准，并在输出的 session_note 里注明——
490	// 不吞这个分歧，让带外调度器/审计能看见「模型报错了会话号」这件事本身。
491	async function cmdTickBegin({ root, flags }) {
492	  const reportedSession = typeof flags.session === 'string' && flags.session.trim() !== ''
493	    ? flags.session.trim()
494	    : null;
495	  const stamped = await readJson(root, RUNTIME_CURRENT_SESSION_PATH);
496	  const stampedSession =
497	    stamped !== null && typeof stamped.session_id === 'string' && stamped.session_id.trim() !== ''
498	      ? stamped.session_id.trim()
499	      : null;
500	
501	  let session;
502	  let sessionNote;
503	  if (stampedSession !== null) {
504	    session = stampedSession;
505	    if (reportedSession !== null && reportedSession !== stampedSession) {
506	      sessionNote =
507	        `--session 报的「${reportedSession}」与机器盖章「${stampedSession}」不一致，` +
508	        '以机器盖章为准（SessionStart 钩子经 session-mark 登记的才是真实会话标识）';
509	    }
510	  } else {
511	    session = reportedSession ?? `进程-${process.pid}`;
512	  }
513	
514	  const options = { session };
515	  if (flags['lease-ms'] !== undefined) {
516	    const leaseMs = Number(flags['lease-ms']);
517	    if (typeof flags['lease-ms'] !== 'string' || !Number.isInteger(leaseMs) || leaseMs <= 0) {
518	      throw new CliError('--lease-ms 需要带一个正整数（毫秒）');
519	    }
520	    options.leaseMs = leaseMs;
521	  }
522	  if (flags.pid !== undefined) {
523	    const pid = Number(flags.pid);
524	    if (typeof flags.pid !== 'string' || !Number.isInteger(pid) || pid <= 0) {
525	      throw new CliError('--pid 需要带一个正整数（进程号）');
526	    }
527	    options.pid = pid;
528	  }
529	
530	  const got = await acquire(root, options);
531	  if (!got.acquired) {
532	    const h = got.holder;
533	    // holder 可能是 null：极端竞争下刚输给别人、对方又立刻放了锁，此时只知道自己没抢到。
534	    const who = h
535	      ? `第 ${h.generation} 代持有者还活着且租约未到期` +
536	        `（进程 ${h.holder?.pid ?? '不明'}，会话 ${h.holder?.session ?? '不明'}，租约到 ${h.lease_expires_at}）`
537	      : '刚被别的会话抢走';
538	    throw new CliError(`锁被占着：${who}`, EXIT.LOCK_HELD);
539	  }
540	
541	  // 序号在取锁时已分配并写进锁文件，这里让状态档跟上（经 store，有指纹有事件）。
542	  const state = await readJson(root, PATHS.state);
543	  if (state === null) {
544	    throw new CliError(`找不到 ${PATHS.state}，项目状态档缺失，没法开工`);
545	  }
546	  state.tick_seq = got.tickSeq;
547	  await writeJson(root, PATHS.state, state, {
548	    actor: '脚本',
549	    event: `tick-begin:第 ${got.tickSeq} 轮（第 ${got.generation} 代）`
550	  });
